mapper.select:
SELECT id, user_id, token_hash, device_name, created_at, last_used_at, expires_at, revoked_at
FROM desktop_device_tokens
WHERE token_hash = #{tokenHash}
  AND revoked_at IS NULL
  AND expires_at > #{now}

mapper.update:
UPDATE desktop_device_tokens
SET last_used_at = #{now}
WHERE id = #{id}

UPDATE desktop_device_tokens
SET revoked_at = #{now}
WHERE token_hash = #{tokenHash}
  AND revoked_at IS NULL

UPDATE desktop_device_tokens
SET revoked_at = #{now}
WHERE user_id = #{userId}
  AND revoked_at IS NULL

mapper.select:
SELECT id, user_id, token_hash, redirect_path, created_at, expires_at, used_at, otp_verified
FROM desktop_sso_tokens
WHERE token_hash = #{tokenHash}
  AND used_at IS NULL
  AND expires_at > #{now}

mapper.update:
UPDATE desktop_sso_tokens
SET used_at = #{now}
WHERE id = #{id}
  AND used_at IS NULL
  AND expires_at > #{now}
